   parabola y=f(x)           → TubeGeometry(radius .035) sampled pts     #2E9BD6
   region R                  → ShapeGeometry, MeshBasicMaterial          #C8E0EF a=.8
   right edge x=2            → Line                                      black
   ticks (4, f(x), 2, x)     → short Lines                               black
   axis of revolution y=c    → Line across whole figure                  #E0403C
   rotation arrow            → TubeGeometry arc (YZ plane) + ConeGeometry black
   washer at x               → RingGeometry rotateY(90°) + 2 LineLoops    silver
   washer radius annotation  → 2 Lines + labels R_out / r_in             #555
   slice segment at x        → Line                                      gray
   solid: outer + end caps   → LatheGeometry(profile).rotateZ(-90°)       silver Phong
   solid: hole wall          → LatheGeometry(2-pt profile) darker         #A6A6A6
   solid rims (outer/inner)  → LineLoop circles (inner darker)            #8A8A8A / #6A6A6A
   cutaway face (region)     → ShapeGeometry on seam half-plane           #C8E0EF
─────────────────────────────────────────────────────────────────────────────*/

const CO = {
  blue: 0x2E9BD6, fill: 0xC8E0EF, red: 0xE0403C,
  silver: 0xDCDCDC, silverDim: 0xA6A6A6,
  rim: 0x8A8A8A, rimDark: 0x5E5E5E, black: 0x111111
};
const X0 = 5.8;                 // solid offset along the shared horizontal axis
const XA = 0, XB = 2;           // interval of integration

const st = {
  fsrc: 'x^2', f: (x) => x * x, c: -1,
  xs: 1, stage: 2, sweep: 1, sweeping: false, sweepT0: 0, tween: null, step: 0,
  showRad: true
};

/* ── lights (brighter, silvery key + fill) ──────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.52));
const dl1 = new THREE.DirectionalLight(0xffffff, 0.85); dl1.position.set(4, 8, 10); scene.add(dl1);
const dl2 = new THREE.DirectionalLight(0xffffff, 0.40); dl2.position.set(-7, -4, 5); scene.add(dl2);
const dl3 = new THREE.DirectionalLight(0xffffff, 0.22); dl3.position.set(0, 3, -8); scene.add(dl3);

/* ── groups ─────────────────────────────────────────────────────────────── */
const gAxes = new THREE.Group();
const gRegion = new THREE.Group();
const gRed = new THREE.Group();
const gRot = new THREE.Group();
const gWasher = new THREE.Group();
const gRad = new THREE.Group();
const gTick = new THREE.Group();
const gSolid = new THREE.Group();
const gFace = new THREE.Group();
[gAxes, gRegion, gRed, gRot, gWasher, gRad, gTick, gSolid, gFace].forEach(g => scene.add(g));

/* ── small helpers ──────────────────────────────────────────────────────── */
const v3 = (x, y, z = 0) => new THREE.Vector3(x, y, z);
function mkLine(pts, color, opacity = 1) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(g, new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity }));
}
function coneTip(pos, dir, color, size = 0.085) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(size, size * 2.8, 18), new THREE.MeshBasicMaterial({ color }));
  m.position.copy(pos);
  m.quaternion.setFromUnitVectors(v3(0, 1, 0), dir.clone().normalize());
  return m;
}
function ringLine(xc, yc, r, color, seg = 108) {
  const pts = [];
  for (let i = 0; i <= seg; i++) { const t = i / seg * Math.PI * 2; pts.push(v3(xc, yc + r * Math.cos(t), r * Math.sin(t))); }
  return mkLine(pts, color);
}
function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.geometry?.dispose?.();
    if (c.material) (Array.isArray(c.material) ? c.material : [c.material]).forEach(m => m.dispose?.());
  }
}
function fv(x) { let y; try { y = st.f(x); } catch { y = NaN; } return Number.isFinite(y) ? y : 0; }
function fmt(v) { return Math.abs(v - Math.round(v)) < 1e-9 ? String(Math.round(v)) : v.toFixed(2); }
function fmtSigned(v) { return (v < 0 ? '\u2212' : '') + fmt(Math.abs(v)); }
// 'x^2' → 'x<sup>2</sup>' ; 'x^(1/2)' → 'x<sup>1/2</sup>'
function sup(srcTxt) {
  return String(srcTxt).replace(/\s+/g, '')
    .replace(/\*/g, '\u00B7')
    .replace(/\^\(([^)]+)\)/g, '<sup>// @FIGURE_CODE_BEGIN</sup>')
    .replace(/\^([-\w.]+)/g, '<sup>// @FIGURE_CODE_BEGIN</sup>');
}

/* ── static 2D frame ────────────────────────────────────────────────────── */
gAxes.add(mkLine([v3(0, -2.45), v3(0, 4.45)], CO.black));
gAxes.add(coneTip(v3(0, 4.62), v3(0, 1, 0), CO.black));
gAxes.add(mkLine([v3(-0.45, 0), v3(2.80, 0)], CO.black));
gAxes.add(coneTip(v3(2.96, 0), v3(1, 0, 0), CO.black));

/* ── axis of revolution + rotation arrow (moved when c changes) ─────────── */
gRed.add(mkLine([v3(-1.70, 0), v3(X0 + 0.5, 0)], CO.red));
(function buildRotArrow() {
  const R = 0.55, xc = 3.95, pts = [];
  for (let i = 0; i <= 64; i++) {
    const t = -0.45 * Math.PI + (i / 64) * (1.85 * Math.PI);
    pts.push(v3(xc, R * Math.cos(t), R * Math.sin(t)));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  gRot.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 90, 0.022, 8, false),
    new THREE.MeshBasicMaterial({ color: CO.black })));
  const p1 = pts[pts.length - 1], p0 = pts[pts.length - 3];
  gRot.add(coneTip(p1, p1.clone().sub(p0), CO.black, 0.06));
})();

/* ── dynamic geometry ───────────────────────────────────────────────────── */
function curvePts(n = 96) {
  const a = [];
  for (let i = 0; i <= n; i++) { const x = XA + (XB - XA) * i / n; a.push(new THREE.Vector2(x, fv(x))); }
  return a;
}

function rebuildRegion() {
  clearGroup(gRegion);
  const pts = curvePts();

  const sh = new THREE.Shape();
  sh.moveTo(XA, 0);
  pts.forEach(p => sh.lineTo(p.x, p.y));
  sh.lineTo(XB, 0); sh.lineTo(XA, 0);
  const rgeo = new THREE.ShapeGeometry(sh);
  if (rgeo.attributes.position && rgeo.attributes.position.count > 2) {
    const rm = new THREE.Mesh(rgeo, new THREE.MeshBasicMaterial({
      color: CO.fill, transparent: true, opacity: 0.80, side: THREE.DoubleSide, depthWrite: false
    }));
    rm.position.z = -0.005;
    gRegion.add(rm);
  } else rgeo.dispose();

  const path = new THREE.CatmullRomCurve3(pts.map(p => v3(p.x, p.y, 0)));
  gRegion.add(new THREE.Mesh(new THREE.TubeGeometry(path, 140, 0.035, 8, false),
    new THREE.MeshBasicMaterial({ color: CO.blue })));

  const f2 = fv(XB);
  gRegion.add(mkLine([v3(XB, 0), v3(XB, f2)], CO.black));
  gRegion.add(mkLine([v3(-0.13, f2), v3(0, f2)], CO.black));
  gRegion.add(mkLine([v3(XB, -0.11), v3(XB, 0)], CO.black));
}

function rebuildWasher() {
  clearGroup(gWasher); clearGroup(gRad); clearGroup(gTick);
  const x = st.xs, c = st.c, y = fv(x);
  const ro = Math.abs(y - c), ri = Math.abs(0 - c);
  const rIn = Math.max(Math.min(ro, ri), 0.002);
  const rOut = Math.max(Math.max(ro, ri), rIn + 0.004);

  const geo = new THREE.RingGeometry(rIn, rOut, 120, 1);
  geo.rotateY(Math.PI / 2);
  const mesh = new THREE.Mesh(geo, new THREE.MeshPhongMaterial({
    color: CO.silver, specular: 0x8a8a8a, shininess: 26,
    side: THREE.DoubleSide, transparent: true, opacity: 0.95
  }));
  mesh.position.set(x, c, 0);
  gWasher.add(mesh);
  gWasher.add(ringLine(x, c, rOut, CO.rim));
  gWasher.add(ringLine(x, c, rIn, CO.rimDark));

  // radius annotation (direction 45° toward the viewer, in the plane x = const)
  const s = Math.SQRT1_2;
  gRad.add(mkLine([v3(x, c, 0), v3(x, c + rOut * s, rOut * s)], 0x555555));
  gRad.add(mkLine([v3(x, c, 0), v3(x, c - rIn * s, -rIn * s)], 0x555555));

  gTick.add(mkLine([v3(x, 0), v3(x, y)], CO.rim, 0.9));
  gTick.add(mkLine([v3(-0.13, y), v3(0, y)], CO.black));
  gTick.add(mkLine([v3(x, -0.10), v3(x, 0)], CO.black));
}

function faceShape() {
  const c = st.c, pts = curvePts(72);
  const sh = new THREE.Shape();
  sh.moveTo(XA, 0 - c);
  pts.forEach(p => sh.lineTo(p.x, p.y - c));
  sh.lineTo(XB, 0 - c);
  sh.lineTo(XA, 0 - c);
  return sh;
}

function rebuildSolid() {
  clearGroup(gSolid); clearGroup(gFace);
  const c = st.c;
  const ri = Math.max(Math.abs(0 - c), 0.002);
  const N = 72;
  const phiLen = Math.max(Math.PI * 2 * st.sweep, 0.0008);

  // outer surface + the two annular end caps (down to the hole radius)
  const prof = [new THREE.Vector2(ri, XA)];
  for (let i = 0; i <= N; i++) {
    const x = XA + (XB - XA) * i / N;
    prof.push(new THREE.Vector2(Math.max(Math.abs(fv(x) - c), 0.002), x));
  }
  prof.push(new THREE.Vector2(ri, XB));

  const geo = new THREE.LatheGeometry(prof, 84, -Math.PI / 2, phiLen);
  geo.rotateZ(-Math.PI / 2);
  const mesh = new THREE.Mesh(geo, new THREE.MeshPhongMaterial({
    color: CO.silver, specular: 0x909090, shininess: 30, side: THREE.DoubleSide
  }));
  mesh.position.set(X0, c, 0);
  gSolid.add(mesh);

  // the cylindrical hole wall, deliberately a darker silver
  const holeGeo = new THREE.LatheGeometry(
    [new THREE.Vector2(ri, XA), new THREE.Vector2(ri, XB)], 84, -Math.PI / 2, phiLen);
  holeGeo.rotateZ(-Math.PI / 2);
  const hole = new THREE.Mesh(holeGeo, new THREE.MeshPhongMaterial({
    color: CO.silverDim, specular: 0x555555, shininess: 14, side: THREE.DoubleSide
  }));
  hole.position.set(X0, c, 0);
  gSolid.add(hole);

  if (st.sweep > 0.999) {
    const rout2 = Math.max(Math.abs(fv(XB) - c), 0.002);
    const rout0 = Math.max(Math.abs(fv(XA) - c), 0.002);
    gSolid.add(ringLine(X0 + XB, c, rout2, CO.rim));
    gSolid.add(ringLine(X0 + XB, c, ri, CO.rimDark));
    gSolid.add(ringLine(X0 + XA, c, rout0, CO.rim));
    gSolid.add(ringLine(X0 + XA, c, ri, CO.rimDark));
  }

  // cutaway face: the generating region drawn on the seam plane
  const fgeo = new THREE.ShapeGeometry(faceShape());
  if (fgeo.attributes.position && fgeo.attributes.position.count > 2) {
    const fm = new THREE.Mesh(fgeo, new THREE.MeshBasicMaterial({
      color: CO.fill, transparent: true, opacity: 0.74, side: THREE.DoubleSide,
      depthTest: false, depthWrite: false
    }));
    fm.position.set(X0, c, 0);
    fm.renderOrder = 10;
    gFace.add(fm);
    const pts = curvePts(72).map(p => v3(p.x, p.y - c, 0));
    const outline = mkLine(pts, CO.blue);
    outline.material.depthTest = false; outline.renderOrder = 11;
    outline.position.set(X0, c, 0);
    gFace.add(outline);
  } else fgeo.dispose();

  // trailing face while the region is being revolved
  if (st.sweep < 0.999) {
    const bgeo = new THREE.ShapeGeometry(faceShape());
    if (bgeo.attributes.position && bgeo.attributes.position.count > 2) {
      const bm = new THREE.Mesh(bgeo, new THREE.MeshBasicMaterial({
        color: 0x9FC4DC, transparent: true, opacity: 0.9, side: THREE.DoubleSide
      }));
      bm.position.set(X0, c, 0);
      bm.rotation.x = phiLen;
      gFace.add(bm);
    } else bgeo.dispose();
  }
}

function applyStage() {
  gWasher.visible = st.stage >= 1;
  gRad.visible = st.stage >= 1 && st.showRad;
  gTick.visible = st.stage >= 1;
  gRot.visible = st.stage >= 1;
  gSolid.visible = st.stage >= 2;
  gFace.visible = st.stage >= 2;
}

/* ── labels ─────────────────────────────────────────────────────────────── */
const L = {};
L.y = addLabel('<i>y</i>', v3(0.20, 4.62), { fontSize: '19px', offset: [8, 0] });
L.x = addLabel('<i>x</i>', v3(3.02, 0.34), { fontSize: '19px' });
L.o = addLabel('0', v3(-0.14, -0.30), { fontSize: '18px' });
L.top = addLabel('4', v3(-0.10, 4), { fontSize: '18px', offset: [-16, 0] });
L.fx = addLabel('<i>x</i><sup>2</sup>', v3(-0.10, 1), { fontSize: '18px', offset: [-22, 0] });
L.two = addLabel('2', v3(2, -0.10), { fontSize: '18px', offset: [0, 18] });
L.xs = addLabel('<i>x</i>', v3(1, -0.10), { fontSize: '18px', offset: [0, 18] });
L.R = addLabel('<i>R</i>', v3(1.40, 1.95), { fontSize: '22px', bold: true });
L.axis = addLabel('<i>y</i> = \u22121', v3(-1.68, -1), { fontSize: '18px', offset: [-38, 0] });
L.rout = addLabel('', v3(0, 0, 0), { fontSize: '13px', color: '#444', background: 'rgba(255,255,255,.75)' });
L.rin = addLabel('', v3(0, 0, 0), { fontSize: '13px', color: '#444', background: 'rgba(255,255,255,.75)' });

function updateLabels() {
  const c = st.c, x = st.xs, y = fv(x), f2 = fv(XB);
  L.top.pos.set(-0.10, f2, 0); L.top.div.innerHTML = fmtSigned(f2);
  L.fx.pos.set(-0.10, y, 0); L.fx.div.innerHTML = '<i>' + sup(st.fsrc) + '</i>';
  L.xs.pos.set(x, -0.10, 0);
  L.axis.pos.set(-1.68, c, 0); L.axis.div.innerHTML = '<i>y</i> = ' + fmtSigned(c);
  const xr = 1.42, yr = Math.max(0.30, fv(xr) * 0.55);
  L.R.pos.set(xr, yr, 0);

  // radius annotations (blanked out when hidden — _syncLabels owns `display`)
  const ro = Math.abs(y - c), ri = Math.abs(0 - c), s = Math.SQRT1_2;
  const on = st.stage >= 1 && st.showRad;
  L.rout.pos.set(x, c + ro * s * 0.62, ro * s * 0.62);
  L.rin.pos.set(x, c - ri * s * 0.66, -ri * s * 0.66);
  L.rout.div.innerHTML = on ? 'R<sub>out</sub> = ' + ro.toFixed(2) : '';
  L.rin.div.innerHTML = on ? 'r<sub>in</sub> = ' + ri.toFixed(2) : '';
}

/* ── readout / volume (all recomputed from the compiled f) ──────────────── */
function area(x) {
  const c = st.c, ro = Math.abs(fv(x) - c), ri = Math.abs(0 - c);
  return Math.PI * Math.max(0, ro * ro - ri * ri);
}
function volume() {
  const n = 400, h = (XB - XA) / n;
  let s = area(XA) + area(XB);
  for (let i = 1; i < n; i++) s += area(XA + i * h) * (i % 2 ? 4 : 2);
  return s * h / 3;
}
function updateReadout() {
  const x = st.xs, c = st.c, ro = Math.abs(fv(x) - c), ri = Math.abs(0 - c);
  const el = document.getElementById('readout');
  if (!el) return;
  el.innerHTML =
    'x = ' + x.toFixed(2) + '&nbsp;&nbsp;f(x) = ' + fv(x).toFixed(3) + '<br>' +
    'R<sub>out</sub> = f(x) \u2212 c = ' + ro.toFixed(3) + '<br>' +
    'r<sub>in</sub> = 0 \u2212 c = ' + ri.toFixed(3) + '<br>' +
    'A(x) = \u03C0(R<sub>out</sub>\u00B2 \u2212 r<sub>in</sub>\u00B2) = ' + area(x).toFixed(3) + '<br>' +
    'V = \u222B<sub>0</sub><sup>2</sup> A dx \u2248 ' + volume().toFixed(3);
}

function rebuildAll() {
  gRed.position.y = st.c;
  gRot.position.y = st.c;
  rebuildRegion();
  rebuildWasher();
  rebuildSolid();
  applyStage();
  if (L.axis) updateLabels();
  updateReadout();
}

/* ── interaction targets ────────────────────────────────────────────────── */
registerInteractive(gWasher, {
  title: 'Representative washer',
  tooltip: 'Washer at x: outer radius f(x)\u2212c, inner radius \u2212c',
  body: 'Revolving the vertical slice of R at x about y = c sweeps a washer. Its outer radius is f(x) \u2212 c and its inner radius is 0 \u2212 c, so its area is \u03C0[(f(x)\u2212c)\u00B2 \u2212 c\u00B2]. For f(x) = x\u00B2 and c = \u22121 this is \u03C0((x\u00B2+1)\u00B2 \u2212 1) = \u03C0(x\u2074 + 2x\u00B2).'
});
registerInteractive(gSolid, {
  title: 'Solid of revolution',
  tooltip: 'Region R revolved about y = c',
  body: 'Stacking every washer from x = 0 to x = 2 gives this flared horn. The cylindrical hole of radius 1 comes from the one-unit gap between the x-axis and the line y = \u22121. Volume = \u222B\u2080\u00B2 \u03C0(x\u2074 + 2x\u00B2) dx = \u03C0(32/5 + 16/3) = 176\u03C0/15 \u2248 36.86.'
});

/* ── equation inputs ────────────────────────────────────────────────────── */
bindEquationInput('fx', (fn, src) => {
  for (let i = 0; i <= 10; i++) {
    const val = fn(XA + (XB - XA) * i / 10);
    if (!Number.isFinite(val)) throw new Error('f(x) is not finite on [0, 2]');
  }
  st.f = fn; st.fsrc = src;
  rebuildAll();
}, { variables: ['x'] });

bindEquationInput('axisC', (fn) => {
  const val = fn(0);
  if (!Number.isFinite(val)) throw new Error('axis must be a number, e.g. -1');
  st.c = val;
  rebuildAll();
}, { variables: [] });

/* ── camera (after all geometry) ────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 66, elevationDeg: 10, rollDeg: 0, heightFraction: 0.78 });

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const slider = document.getElementById('xPos');
const xOut = document.getElementById('xOut');

function setX(val) {
  st.xs = Math.min(XB, Math.max(XA, val));
  slider.value = String(st.xs);
  xOut.textContent = st.xs.toFixed(2);
  rebuildWasher();
  applyStage();
  updateLabels();
  updateReadout();
}
slider.addEventListener('input', () => { st.tween = null; setX(parseFloat(slider.value)); });

const stageBtns = Array.from(document.querySelectorAll('#stageBtns button'));
function setStage(s) {
  st.stage = s;
  stageBtns.forEach(b => b.classList.toggle('active', Number(b.dataset.stage) === s));
  applyStage();
  updateLabels();
}
stageBtns.forEach(b => b.addEventListener('click', () => setStage(Number(b.dataset.stage))));

document.getElementById('chkRad').addEventListener('change', (e) => {
  st.showRad = e.target.checked;
  applyStage();
  updateLabels();
});

document.getElementById('btnSweep').addEventListener('click', () => {
  setStage(2);
  st.sweep = 0; st.sweeping = true; st.sweepT0 = performance.now();
  rebuildSolid();
});

/* ── guided demo ────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'The region R', n: 'The region R lies under y = x\u00B2 from x = 0 to x = 2, above the x-axis. The red line y = \u22121 sits one unit below the x-axis and will be the axis of revolution.', stage: 0, x: 1 },
  { t: 'A representative washer', n: 'Slice R vertically at x and revolve that slice: it sweeps a washer of outer radius x\u00B2+1 and inner radius 1, area \u03C0((x\u00B2+1)\u00B2 \u2212 1) = \u03C0(x\u2074 + 2x\u00B2).', stage: 1, x: 1 },
  { t: 'Sweep along the interval', n: 'Drag x toward 2 and watch the washer flare: at x = 2 the outer radius is 5 while the hole stays at radius 1.', stage: 1, x: 2 },
  { t: 'The full solid', n: 'Stacking every washer from x = 0 to x = 2 gives the horn-shaped solid with a cylindrical hole of radius 1; its volume is \u222B\u2080\u00B2 \u03C0(x\u2074+2x\u00B2) dx = \u03C0(32/5 + 16/3) = 176\u03C0/15 \u2248 36.86.', stage: 2, x: 2 }
];
const demoBox = document.getElementById('demoBox');
function goToStep(i) {
  st.step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[st.step];
  setStage(s.stage);
  st.tween = { from: st.xs, to: s.x, t0: performance.now(), dur: 750 };
  demoBox.innerHTML = '<b>' + (st.step + 1) + '. ' + s.t + '</b><br>' + s.n;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(st.step + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(st.step - 1));
demoBox.innerHTML = '<b>Press “Next ▶” to walk through the washer method.</b>';

/* ── tween / sweep loop ─────────────────────────────────────────────────── */
function tickFig() {
  requestAnimationFrame(tickFig);
  const now = performance.now();
  if (st.tween) {
    const p = Math.min(1, (now - st.tween.t0) / st.tween.dur);
    const e = p * p * (3 - 2 * p);
    setX(st.tween.from + (st.tween.to - st.tween.from) * e);
    if (p >= 1) st.tween = null;
  }
  if (st.sweeping) {
    const p = Math.min(1, (now - st.sweepT0) / 2600);
    st.sweep = p;
    rebuildSolid();
    applyStage();
    if (p >= 1) { st.sweeping = false; st.sweep = 1; rebuildSolid(); applyStage(); }
  }
}
tickFig();

setStage(2);
setX(1);
