    .replace(/\*/g, '\u00B7')
    .replace(/\^\(([^)]+)\)/g, '<sup>// @FIGURE_CODE_BEGIN</sup>')
    .replace(/\^([-\w.]+)/g, '<sup>// @FIGURE_CODE_BEGIN</sup>');
}

